-- ════════════════════════════════════════════════════════════════════
--  SKYHIGH — ONE-TIME SUPABASE SETUP   (generated by scripts/build-setup-sql.mjs)
--
--  1. Change the email on the LAST LINE to the owner's email address.
--  2. Supabase dashboard → SQL Editor → New query → paste this whole file → Run.
--  3. Authentication → Users → Add user (that email + a password, Auto Confirm), then sign in at <your-site>/admin.
--
--  Safe to run again after updates.
-- ════════════════════════════════════════════════════════════════════

-- ▸ 20261125000000_init.sql
-- ════════════════════════════════════════════════════════════════════
--  Skyhigh — initial schema
--  Tables: admin_users, enquiries, services, destinations, packages, site_settings
--  Security: Row Level Security on every table; admin rights via is_admin().
-- ════════════════════════════════════════════════════════════════════


-- ── Roles ───────────────────────────────────────────────────────────
-- Administrators are Supabase Auth users listed here. Add the first admin
-- manually (see README): insert into admin_users (user_id, role) values ('<uuid>', 'admin');
create table if not exists public.admin_users (
  user_id    uuid primary key references auth.users (id) on delete cascade,
  role       text not null default 'editor' check (role in ('admin', 'editor')),
  created_at timestamptz not null default now()
);
alter table public.admin_users enable row level security;

create or replace function public.is_admin()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (select 1 from public.admin_users where user_id = auth.uid());
$$;

create or replace function public.is_owner()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (select 1 from public.admin_users where user_id = auth.uid() and role = 'admin');
$$;

revoke all on function public.is_admin() from public;
revoke all on function public.is_owner() from public;
grant execute on function public.is_admin() to anon, authenticated;
grant execute on function public.is_owner() to authenticated;

drop policy if exists "admins read admin list" on public.admin_users;
create policy "admins read admin list" on public.admin_users
  for select to authenticated using (public.is_admin());
drop policy if exists "owners manage admin list" on public.admin_users;
create policy "owners manage admin list" on public.admin_users
  for all to authenticated using (public.is_owner()) with check (public.is_owner());

-- ── Enquiries ───────────────────────────────────────────────────────
create table if not exists public.enquiries (
  id          uuid primary key default gen_random_uuid(),
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  full_name   text not null check (char_length(full_name) between 2 and 80),
  email       text not null check (char_length(email) <= 160 and email ~* '^[^@\s]+@[^@\s]+\.[^@\s]+$'),
  phone       text not null check (phone ~ '^\+?[0-9 ()-]{7,20}$'),
  service     text not null check (service in ('tour','transport-passenger','transport-goods','logistics','booking','corporate','custom-package')),
  departure   text not null check (char_length(departure) between 2 and 120),
  destination text not null check (char_length(destination) between 2 and 120),
  travel_date date not null,
  travellers  int check (travellers between 1 and 500),
  budget      text check (char_length(budget) <= 60),
  details     jsonb not null default '{}'::jsonb check (pg_column_size(details) < 4000),
  message     text check (char_length(message) <= 2000),
  consent     boolean not null check (consent = true),
  status      text not null default 'new' check (status in ('new','contacted','quoted','closed','spam')),
  admin_notes text check (char_length(admin_notes) <= 4000),
  source_page text check (char_length(source_page) <= 200)
);
create index if not exists enquiries_created_idx on public.enquiries (created_at desc);
create index if not exists enquiries_status_idx on public.enquiries (status);
create index if not exists enquiries_email_idx on public.enquiries (lower(email), created_at desc);
alter table public.enquiries enable row level security;

-- Public visitors may only INSERT a fresh enquiry; they can never read any.
drop policy if exists "public can submit enquiries" on public.enquiries;
create policy "public can submit enquiries" on public.enquiries
  for insert to anon, authenticated
  with check (status = 'new' and admin_notes is null and consent = true);
drop policy if exists "admins read enquiries" on public.enquiries;
create policy "admins read enquiries" on public.enquiries
  for select to authenticated using (public.is_admin());
drop policy if exists "admins update enquiries" on public.enquiries;
create policy "admins update enquiries" on public.enquiries
  for update to authenticated using (public.is_admin()) with check (public.is_admin());
drop policy if exists "owners delete enquiries" on public.enquiries;
create policy "owners delete enquiries" on public.enquiries
  for delete to authenticated using (public.is_owner());

-- Server-side spam protection: max 5 enquiries per email per hour, 30 per hour overall burst guard,
-- and strip angle brackets from free text.
create or replace function public.enquiries_before_insert()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  recent_by_email int;
  recent_total int;
begin
  if new.travel_date < (now() at time zone 'Asia/Kolkata')::date - 1 then
    raise exception 'travel date must be today or later' using errcode = '23514';
  end if;
  select count(*) into recent_by_email from public.enquiries
    where lower(email) = lower(new.email) and created_at > now() - interval '1 hour';
  if recent_by_email >= 5 then
    raise exception 'rate limit: too many enquiries from this email' using errcode = 'P0001';
  end if;
  select count(*) into recent_total from public.enquiries where created_at > now() - interval '5 minutes';
  if recent_total >= 30 then
    raise exception 'rate limit: please try again shortly' using errcode = 'P0001';
  end if;
  new.full_name   := regexp_replace(new.full_name, '[<>]', '', 'g');
  new.departure   := regexp_replace(new.departure, '[<>]', '', 'g');
  new.destination := regexp_replace(new.destination, '[<>]', '', 'g');
  new.message     := regexp_replace(coalesce(new.message, ''), '[<>]', '', 'g');
  new.email       := lower(trim(new.email));
  new.status      := 'new';
  new.admin_notes := null;
  return new;
end;
$$;
drop trigger if exists enquiries_before_insert on public.enquiries;
create trigger enquiries_before_insert before insert on public.enquiries
  for each row execute function public.enquiries_before_insert();

create or replace function public.touch_updated_at()
returns trigger language plpgsql as $$
begin new.updated_at := now(); return new; end; $$;
drop trigger if exists enquiries_touch on public.enquiries;
create trigger enquiries_touch before update on public.enquiries
  for each row execute function public.touch_updated_at();

-- ── Content (services, destinations, packages) ─────────────────────
-- Each row stores the full typed object in `data` (mirrors src/types/content.ts).
do $$
declare t text;
begin
  foreach t in array array['services','destinations','packages'] loop
    execute format($f$
      create table if not exists public.%1$I (
        id         uuid primary key default gen_random_uuid(),
        slug       text not null unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
        data       jsonb not null,
        published  boolean not null default true,
        sort       int not null default 0,
        updated_at timestamptz not null default now()
      );
      alter table public.%1$I enable row level security;
      drop policy if exists "public reads published %1$s" on public.%1$I;
      create policy "public reads published %1$s" on public.%1$I
        for select to anon, authenticated using (published or public.is_admin());
      drop policy if exists "admins write %1$s" on public.%1$I;
      create policy "admins write %1$s" on public.%1$I
        for all to authenticated using (public.is_admin()) with check (public.is_admin());
      drop trigger if exists %1$s_touch on public.%1$I;
      create trigger %1$s_touch before update on public.%1$I
        for each row execute function public.touch_updated_at();
    $f$, t);
  end loop;
end $$;

-- ── Site settings (contact, seo) ───────────────────────────────────
create table if not exists public.site_settings (
  key        text primary key check (key in ('contact', 'seo')),
  value      jsonb not null,
  updated_at timestamptz not null default now()
);
alter table public.site_settings enable row level security;
drop policy if exists "public reads settings" on public.site_settings;
create policy "public reads settings" on public.site_settings
  for select to anon, authenticated using (true);
drop policy if exists "admins write settings" on public.site_settings;
create policy "admins write settings" on public.site_settings
  for all to authenticated using (public.is_admin()) with check (public.is_admin());

-- Grants (RLS still applies)
grant usage on schema public to anon, authenticated;
grant insert on public.enquiries to anon, authenticated;
grant select, update, delete on public.enquiries to authenticated;
grant select on public.services, public.destinations, public.packages, public.site_settings to anon, authenticated;
grant insert, update, delete on public.services, public.destinations, public.packages, public.site_settings to authenticated;
grant select, insert, update, delete on public.admin_users to authenticated;


-- ▸ 20261126000000_cms.sql
-- ════════════════════════════════════════════════════════════════════
--  Skyhigh CMS — team invites, roles, editable page copy, photo storage
--  Safe to run more than once.
-- ════════════════════════════════════════════════════════════════════

-- ── Editable website copy keys ─────────────────────────────────────
alter table public.site_settings drop constraint if exists site_settings_key_check;
alter table public.site_settings add constraint site_settings_key_check
  check (key in ('contact', 'seo', 'home', 'company', 'pages', 'faqs', 'legal'));

-- ── Roles: editors edit, owners (role = 'admin') also delete & manage team ──
create or replace function public.my_role()
returns text
language sql
stable
security definer
set search_path = public
as $$
  select role from public.admin_users where user_id = auth.uid();
$$;
revoke all on function public.my_role() from public;
grant execute on function public.my_role() to authenticated;

-- Content: anyone on the team can create/edit, only owners can delete.
do $$
declare t text;
begin
  foreach t in array array['services','destinations','packages'] loop
    execute format('drop policy if exists "admins write %1$s" on public.%1$I', t);
    execute format('drop policy if exists "team inserts %1$s" on public.%1$I', t);
    execute format('drop policy if exists "team updates %1$s" on public.%1$I', t);
    execute format('drop policy if exists "owners delete %1$s" on public.%1$I', t);
    execute format('create policy "team inserts %1$s" on public.%1$I for insert to authenticated with check (public.is_admin())', t);
    execute format('create policy "team updates %1$s" on public.%1$I for update to authenticated using (public.is_admin()) with check (public.is_admin())', t);
    execute format('create policy "owners delete %1$s" on public.%1$I for delete to authenticated using (public.is_owner())', t);
  end loop;
end $$;

-- ── Team invites ───────────────────────────────────────────────────
create table if not exists public.admin_invites (
  email      text primary key check (email = lower(email) and email ~* '^[^@\s]+@[^@\s]+\.[^@\s]+$'),
  role       text not null default 'editor' check (role in ('admin', 'editor')),
  invited_by uuid references auth.users (id) on delete set null,
  created_at timestamptz not null default now()
);
alter table public.admin_invites enable row level security;
drop policy if exists "owners read invites" on public.admin_invites;
create policy "owners read invites" on public.admin_invites for select to authenticated using (public.is_owner());

-- Called right after sign-in: turns a pending invite for this email into team membership.
create or replace function public.claim_invite()
returns boolean
language plpgsql
security definer
set search_path = public, auth
as $$
declare
  v_email text;
  v_role text;
begin
  if auth.uid() is null then return false; end if;
  select lower(email) into v_email from auth.users where id = auth.uid();
  select role into v_role from public.admin_invites where email = v_email;
  if v_role is null then return false; end if;
  insert into public.admin_users (user_id, role) values (auth.uid(), v_role)
    on conflict (user_id) do update set role = excluded.role;
  delete from public.admin_invites where email = v_email;
  return true;
end;
$$;

create or replace function public.list_team()
returns table (user_id uuid, email text, role text, pending boolean, created_at timestamptz)
language plpgsql
stable
security definer
set search_path = public, auth
as $$
begin
  if not public.is_owner() then raise exception 'only owners can view the team' using errcode = '42501'; end if;
  return query
    select a.user_id, u.email::text, a.role, false, a.created_at
      from public.admin_users a join auth.users u on u.id = a.user_id
    union all
    select null::uuid, i.email, i.role, true, i.created_at from public.admin_invites i
    order by 5;
end;
$$;

create or replace function public.invite_member(p_email text, p_role text)
returns void
language plpgsql
security definer
set search_path = public, auth
as $$
declare
  v_email text := lower(trim(p_email));
  v_uid uuid;
begin
  if not public.is_owner() then raise exception 'only owners can invite people' using errcode = '42501'; end if;
  if p_role not in ('admin', 'editor') then raise exception 'invalid role'; end if;
  select id into v_uid from auth.users where lower(email) = v_email;
  if v_uid is not null then
    insert into public.admin_users (user_id, role) values (v_uid, p_role)
      on conflict (user_id) do update set role = excluded.role;
  else
    insert into public.admin_invites (email, role, invited_by) values (v_email, p_role, auth.uid())
      on conflict (email) do update set role = excluded.role, invited_by = excluded.invited_by;
  end if;
end;
$$;

create or replace function public.remove_member(p_email text)
returns void
language plpgsql
security definer
set search_path = public, auth
as $$
declare
  v_email text := lower(trim(p_email));
  v_uid uuid;
begin
  if not public.is_owner() then raise exception 'only owners can remove people' using errcode = '42501'; end if;
  select id into v_uid from auth.users where lower(email) = v_email;
  if v_uid = auth.uid() then raise exception 'you cannot remove yourself'; end if;
  if v_uid is not null
     and (select role from public.admin_users where user_id = v_uid) = 'admin'
     and (select count(*) from public.admin_users where role = 'admin') <= 1 then
    raise exception 'the last owner cannot be removed';
  end if;
  delete from public.admin_users where user_id = v_uid;
  delete from public.admin_invites where email = v_email;
end;
$$;

revoke all on function public.claim_invite() from public;
revoke all on function public.list_team() from public;
revoke all on function public.invite_member(text, text) from public;
revoke all on function public.remove_member(text) from public;
grant execute on function public.claim_invite() to authenticated;
grant execute on function public.list_team() to authenticated;
grant execute on function public.invite_member(text, text) to authenticated;
grant execute on function public.remove_member(text) to authenticated;
grant select on public.admin_invites to authenticated;

-- ── Photo storage ──────────────────────────────────────────────────
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('media', 'media', true, 5242880, array['image/webp', 'image/jpeg', 'image/png', 'image/avif', 'image/gif'])
on conflict (id) do update
  set public = true, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;

drop policy if exists "media is public" on storage.objects;
drop policy if exists "team uploads media" on storage.objects;
drop policy if exists "team updates media" on storage.objects;
drop policy if exists "owners delete media" on storage.objects;
create policy "media is public" on storage.objects for select using (bucket_id = 'media');
create policy "team uploads media" on storage.objects for insert to authenticated with check (bucket_id = 'media' and public.is_admin());
create policy "team updates media" on storage.objects for update to authenticated using (bucket_id = 'media' and public.is_admin());
create policy "owners delete media" on storage.objects for delete to authenticated using (bucket_id = 'media' and public.is_owner());


-- ▸ 20261127000000_customers.sql
-- Customer accounts, booking requests, reviews and travel-agent (B2B) rates.
-- Idempotent: safe to run more than once.
--
-- Security model
--  * Customers sign up with email + password (Supabase Auth). A profile row is created for them automatically.
--  * Customers can only ever see and change their own profile, bookings and reviews.
--  * Prices on a booking are filled in by the database from the package / agent rate — never trusted from the browser.
--  * Agent status can only be changed by the admin; agent rates are readable only by approved agents and the admin.
--  * Admin access still comes only from public.admin_users (a customer account never becomes an admin).

-- ── Profiles ─────────────────────────────────────────────────────────
create table if not exists public.customer_profiles (
  user_id      uuid primary key references auth.users (id) on delete cascade,
  full_name    text not null default '' check (char_length(full_name) <= 120),
  phone        text not null default '' check (char_length(phone) <= 30),
  city         text not null default '' check (char_length(city) <= 80),
  agent_status text not null default 'none' check (agent_status in ('none', 'pending', 'approved', 'rejected')),
  agency_name  text not null default '' check (char_length(agency_name) <= 160),
  agency_gstin text not null default '' check (char_length(agency_gstin) <= 20),
  agency_note  text not null default '' check (char_length(agency_note) <= 1000),
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);
alter table public.customer_profiles enable row level security;

drop policy if exists "own profile readable" on public.customer_profiles;
create policy "own profile readable" on public.customer_profiles
  for select to authenticated using (user_id = auth.uid() or public.is_admin());
drop policy if exists "own profile editable" on public.customer_profiles;
create policy "own profile editable" on public.customer_profiles
  for update to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid());

-- Customers may only edit these columns themselves; agent status goes through the functions below.
revoke all on public.customer_profiles from anon, authenticated;
grant select on public.customer_profiles to authenticated;
grant update (full_name, phone, city) on public.customer_profiles to authenticated;

-- Create a profile for every new login (name and phone come from the sign-up form).
create or replace function public.handle_new_customer()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  insert into public.customer_profiles (user_id, full_name, phone)
  values (
    new.id,
    left(coalesce(new.raw_user_meta_data ->> 'full_name', ''), 120),
    left(coalesce(new.raw_user_meta_data ->> 'phone', ''), 30)
  )
  on conflict (user_id) do nothing;
  return new;
end;
$$;
drop trigger if exists on_auth_user_created_customer on auth.users;
create trigger on_auth_user_created_customer after insert on auth.users
  for each row execute function public.handle_new_customer();

-- Profiles for accounts that existed before this migration.
insert into public.customer_profiles (user_id)
select id from auth.users on conflict (user_id) do nothing;

create or replace function public.is_approved_agent()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (select 1 from public.customer_profiles where user_id = auth.uid() and agent_status = 'approved');
$$;
revoke all on function public.is_approved_agent() from public;
grant execute on function public.is_approved_agent() to authenticated;

-- A customer applies to become a travel agent.
create or replace function public.request_agent_access(p_agency text, p_gstin text, p_note text)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.uid() is null then raise exception 'sign in first' using errcode = '42501'; end if;
  if char_length(coalesce(trim(p_agency), '')) < 2 then raise exception 'Please enter your agency name'; end if;
  update public.customer_profiles
     set agent_status = case when agent_status = 'approved' then 'approved' else 'pending' end,
         agency_name  = left(trim(p_agency), 160),
         agency_gstin = left(upper(trim(coalesce(p_gstin, ''))), 20),
         agency_note  = left(trim(coalesce(p_note, '')), 1000),
         updated_at   = now()
   where user_id = auth.uid();
end;
$$;
revoke all on function public.request_agent_access(text, text, text) from public;
grant execute on function public.request_agent_access(text, text, text) to authenticated;

-- Admin: approve / reject an agent.
create or replace function public.set_agent_status(p_user uuid, p_status text)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if not public.is_admin() then raise exception 'admins only' using errcode = '42501'; end if;
  if p_status not in ('none', 'pending', 'approved', 'rejected') then raise exception 'bad status'; end if;
  update public.customer_profiles set agent_status = p_status, updated_at = now() where user_id = p_user;
end;
$$;
revoke all on function public.set_agent_status(uuid, text) from public;
grant execute on function public.set_agent_status(uuid, text) to authenticated;

-- Admin: customer list with emails (auth.users is not readable directly).
create or replace function public.admin_list_customers()
returns table (
  user_id uuid, email text, full_name text, phone text, city text,
  agent_status text, agency_name text, agency_gstin text, agency_note text,
  created_at timestamptz, last_sign_in_at timestamptz, bookings bigint, is_admin boolean
)
language plpgsql
stable
security definer
set search_path = public, auth
as $$
begin
  if not public.is_admin() then raise exception 'admins only' using errcode = '42501'; end if;
  return query
    select p.user_id, u.email::text, p.full_name, p.phone, p.city,
           p.agent_status, p.agency_name, p.agency_gstin, p.agency_note,
           u.created_at, u.last_sign_in_at,
           (select count(*) from public.bookings b where b.user_id = p.user_id),
           exists (select 1 from public.admin_users a where a.user_id = p.user_id)
      from public.customer_profiles p
      join auth.users u on u.id = p.user_id
     order by u.created_at desc;
end;
$$;

-- ── Agent (B2B) rates ────────────────────────────────────────────────
create table if not exists public.agent_rates (
  package_slug     text primary key check (char_length(package_slug) between 1 and 120),
  price_per_person numeric(12, 2) not null check (price_per_person > 0),
  note             text not null default '' check (char_length(note) <= 300),
  updated_at       timestamptz not null default now()
);
alter table public.agent_rates enable row level security;
drop policy if exists "agents and admin read rates" on public.agent_rates;
create policy "agents and admin read rates" on public.agent_rates
  for select to authenticated using (public.is_admin() or public.is_approved_agent());
drop policy if exists "admin writes rates" on public.agent_rates;
create policy "admin writes rates" on public.agent_rates
  for all to authenticated using (public.is_admin()) with check (public.is_admin());
revoke all on public.agent_rates from anon;

-- ── Bookings ─────────────────────────────────────────────────────────
create table if not exists public.bookings (
  id               uuid primary key default gen_random_uuid(),
  user_id          uuid not null default auth.uid() references auth.users (id) on delete cascade,
  package_slug     text not null check (char_length(package_slug) between 1 and 120),
  package_title    text not null check (char_length(package_title) between 1 and 200),
  travel_date      date not null,
  adults           int  not null check (adults between 1 and 60),
  children         int  not null default 0 check (children between 0 and 60),
  contact_name     text not null check (char_length(contact_name) between 2 and 120),
  contact_phone    text not null check (char_length(contact_phone) between 6 and 30),
  contact_email    text,
  notes            text check (char_length(notes) <= 2000),
  price_per_person numeric(12, 2),
  rate_type        text not null default 'public' check (rate_type in ('public', 'agent')),
  status           text not null default 'pending' check (status in ('pending', 'confirmed', 'cancelled', 'completed')),
  admin_notes      text check (char_length(admin_notes) <= 4000),
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now()
);
create index if not exists bookings_user_idx on public.bookings (user_id, created_at desc);
create index if not exists bookings_status_idx on public.bookings (status, created_at desc);
alter table public.bookings enable row level security;

drop policy if exists "customers create own bookings" on public.bookings;
create policy "customers create own bookings" on public.bookings
  for insert to authenticated with check (user_id = auth.uid() and status = 'pending' and admin_notes is null);
drop policy if exists "own bookings readable" on public.bookings;
create policy "own bookings readable" on public.bookings
  for select to authenticated using (user_id = auth.uid() or public.is_admin());
drop policy if exists "admin updates bookings" on public.bookings;
create policy "admin updates bookings" on public.bookings
  for update to authenticated using (public.is_admin()) with check (public.is_admin());
drop policy if exists "owner deletes bookings" on public.bookings;
create policy "owner deletes bookings" on public.bookings
  for delete to authenticated using (public.is_owner());
revoke all on public.bookings from anon;

-- Fill in trusted values on every new booking.
create or replace function public.prepare_booking()
returns trigger
language plpgsql
security definer
set search_path = public, auth
as $$
declare
  v_agent numeric;
  v_public numeric;
  v_title text;
begin
  if new.travel_date < current_date then raise exception 'Travel date must be today or later'; end if;
  if (select count(*) from public.bookings where user_id = new.user_id and status = 'pending') >= 10 then
    raise exception 'You already have 10 pending booking requests. Please wait for us to confirm them.';
  end if;
  select email into new.contact_email from auth.users where id = new.user_id;

  select nullif(data ->> 'pricePerPerson', '')::numeric, data ->> 'title'
    into v_public, v_title
    from public.packages where slug = new.package_slug and published;
  if v_title is not null then new.package_title := left(v_title, 200); end if;

  if public.is_approved_agent() then
    select price_per_person into v_agent from public.agent_rates where package_slug = new.package_slug;
  end if;
  if v_agent is not null then
    new.price_per_person := v_agent;
    new.rate_type := 'agent';
  else
    new.price_per_person := v_public;
    new.rate_type := 'public';
  end if;
  new.status := 'pending';
  new.created_at := now();
  new.updated_at := now();
  return new;
end;
$$;
drop trigger if exists bookings_prepare on public.bookings;
create trigger bookings_prepare before insert on public.bookings
  for each row execute function public.prepare_booking();

create or replace function public.touch_updated_at()
returns trigger language plpgsql as $$
begin
  new.updated_at := now();
  return new;
end;
$$;
drop trigger if exists bookings_touch on public.bookings;
create trigger bookings_touch before update on public.bookings
  for each row execute function public.touch_updated_at();

-- A customer may cancel their own booking while it is still pending.
create or replace function public.cancel_my_booking(p_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  update public.bookings set status = 'cancelled'
   where id = p_id and user_id = auth.uid() and status = 'pending';
  if not found then raise exception 'Only pending bookings can be cancelled online. Please contact us.'; end if;
end;
$$;
revoke all on function public.cancel_my_booking(uuid) from public;
grant execute on function public.cancel_my_booking(uuid) to authenticated;

-- ── Reviews ──────────────────────────────────────────────────────────
create table if not exists public.reviews (
  id           uuid primary key default gen_random_uuid(),
  user_id      uuid not null default auth.uid() references auth.users (id) on delete cascade,
  package_slug text not null check (char_length(package_slug) between 1 and 120),
  rating       int  not null check (rating between 1 and 5),
  title        text not null default '' check (char_length(title) <= 120),
  body         text not null check (char_length(body) between 10 and 2000),
  author_name  text not null check (char_length(author_name) between 2 and 80),
  status       text not null default 'pending' check (status in ('pending', 'approved', 'rejected')),
  created_at   timestamptz not null default now(),
  unique (user_id, package_slug)
);
create index if not exists reviews_pkg_idx on public.reviews (package_slug, status, created_at desc);
alter table public.reviews enable row level security;

-- Only customers with a confirmed or completed booking for that package can review it.
drop policy if exists "travellers write reviews" on public.reviews;
create policy "travellers write reviews" on public.reviews
  for insert to authenticated with check (
    user_id = auth.uid() and status = 'pending'
    and exists (
      select 1 from public.bookings b
       where b.user_id = auth.uid() and b.package_slug = reviews.package_slug and b.status in ('confirmed', 'completed')
    )
  );
drop policy if exists "approved reviews are public" on public.reviews;
create policy "approved reviews are public" on public.reviews
  for select to anon, authenticated using (status = 'approved' or user_id = auth.uid() or public.is_admin());
drop policy if exists "admin moderates reviews" on public.reviews;
create policy "admin moderates reviews" on public.reviews
  for update to authenticated using (public.is_admin()) with check (public.is_admin());
drop policy if exists "admin deletes reviews" on public.reviews;
create policy "admin deletes reviews" on public.reviews
  for delete to authenticated using (public.is_admin());

-- Anonymous visitors only need the public columns.
revoke all on public.reviews from anon;
grant select (id, package_slug, rating, title, body, author_name, status, created_at) on public.reviews to anon;

revoke all on function public.admin_list_customers() from public;
grant execute on function public.admin_list_customers() to authenticated;


